      "claim": "Orders timeouts led to gateway service calls to orders timing out, as shown by gateway logs reporting upstream_timeout to orders.",
      "status": "confirmed",
      "cites": ["gateway-L00049"]
    },
    {
      "claim": "Gateway timeouts resulted in 5xx errors being returned to clients, reflected in the gateway's err5xx count spike and internal error logs.",
      "status": "confirmed",
      "cites": ["gateway-M000e"]
    }
  ],
  "alternatives": [
    {
      "category": "retry_amplification",
      "service": "orders",
